   148    inline void fini (void)
   149    {
   150      TopDictValues<>::fini ();
   151    }
   152
   153    inline unsigned int calculate_serialized_size (void) const
   154    {
   155      unsigned int size = 0;
   156      for (unsigned int i = 0; i < get_count (); i++)
   157      {
   158        OpCode op = get_value (i).op;
   159        switch (op)
   160        {
   161          case OpCode_vstore:
   162          case OpCode_FDSelect:
   163            size += OpCode_Size (OpCode_longintdict) + 4 + OpCode_Size (op);
   164            break;
   165          default:
   166            size += TopDictValues<>::calculate_serialized_op_size (get_value (i));
   167            break;
   168        }
   169      }
   170      return size;
   171    }
   172
   173    unsigned int  vstoreOffset;
   174    unsigned int  FDSelectOffset;
