    32  struct ExtentsParam
    33  {
    34    inline void init (void)
    35    {
    36      path_open = false;
    37      min_x.set_int (0x7FFFFFFF);
    38      min_y.set_int (0x7FFFFFFF);
    39      max_x.set_int (-0x80000000);
    40      max_y.set_int (-0x80000000);
    41    }
    42
    43    inline void start_path (void) { path_open = true; }
    44    inline void end_path (void) { path_open = false; }
    45    inline bool is_path_open (void) const { return path_open; }
    46
    47    inline void update_bounds (const Point &pt)
    48    {
    49      if (pt.x < min_x) min_x = pt.x;
    50      if (pt.x > max_x) max_x = pt.x;
    51      if (pt.y < min_y) min_y = pt.y;
    52      if (pt.y > max_y) max_y = pt.y;
    53    }
    54
    55    bool  path_open;
    56    Number min_x;
    57    Number min_y;
    58    Number max_x;
    59    Number max_y;
    60  };
    61
    62  struct CFF2PathProcs_Extents : PathProcs<CFF2PathProcs_Extents, CFF2CSInterpEnv, ExtentsParam>
    63  {
    64    static inline void moveto (CFF2CSInterpEnv &env, ExtentsParam& param, const Point &pt)
    65    {
    66      param.end_path ();
    67      env.moveto (pt);
    68    }
    69
    70    static inline void line (CFF2CSInterpEnv &env, ExtentsParam& param, const Point &pt1)
    71    {
    72      if (!param.is_path_open ())
    73      {
    74        param.start_path ();
    75        param.update_bounds (env.get_pt ());
    76      }
    77      env.moveto (pt1);
    78      param.update_bounds (env.get_pt ());
    79    }
    80
    81    static inline void curve (CFF2CSInterpEnv &env, ExtentsParam& param, const Point &pt1, const Point &pt2, const Point &pt3)
    82    {
    83      if (!param.is_path_open ())
    84      {
    85        param.start_path ();
    86        param.update_bounds (env.get_pt ());
    87      }
    88      /* include control points */
    89      param.update_bounds (pt1);
    90      param.update_bounds (pt2);
    91      env.moveto (pt3);
    92      param.update_bounds (env.get_pt ());
    93    }
    94  };
