   766  template <typename ARG=Number>
   767  struct OpSet
   768  {
   769    static inline void process_op (OpCode op, InterpEnv<ARG>& env)
   770    {
   771      switch (op) {
   772        case OpCode_shortint:
   773          env.argStack.push_int ((int16_t)((env.substr[0] << 8) | env.substr[1]));
   774          env.substr.inc (2);
   775          break;
   776
   777        case OpCode_TwoBytePosInt0: case OpCode_TwoBytePosInt1:
   778        case OpCode_TwoBytePosInt2: case OpCode_TwoBytePosInt3:
   779          env.argStack.push_int ((int16_t)((op - OpCode_TwoBytePosInt0) * 256 + env.substr[0] + 108));
   780          env.substr.inc ();
   781          break;
   782
   783        case OpCode_TwoByteNegInt0: case OpCode_TwoByteNegInt1:
   784        case OpCode_TwoByteNegInt2: case OpCode_TwoByteNegInt3:
   785          env.argStack.push_int ((int16_t)(-(op - OpCode_TwoByteNegInt0) * 256 - env.substr[0] - 108));
   786          env.substr.inc ();
   787          break;
   788
   789        default:
   790          /* 1-byte integer */
   791          if (likely ((OpCode_OneByteIntFirst <= op) && (op <= OpCode_OneByteIntLast)))
   792          {
   793            env.argStack.push_int ((int)op - 139);
   794          } else {
   795            /* invalid unknown operator */
   796            env.clear_args ();
   797            env.set_error ();
   798          }
   799          break;
   800      }
   801    }
   802  };
